UPDATE "ec_pages" SET "content" = '[{"_type":"block","_key":"key-2-lcqrf","style":"h1","children":[{"_type":"span","_key":"key-1-ap11x","text":"Voima-Jyri 500 -projekti"}]},{"_type":"block","_key":"key-5-btxxi","style":"h2","children":[{"_type":"span","_key":"key-4-46f8o","text":""}],"markDefs":[{"_type":"link","_key":"key-3-fstul","href":"/_emdash/api/media/file/01KZ3GKFCXP8DG6T1YY89TXK8K.jpg"}]},{"_type":"block","_key":"key-7-en7i1","style":"h2","children":[{"_type":"span","_key":"key-6-74azc","text":"Mistä on kysymys?"}]},{"_type":"block","_key":"key-10-4ie6e","style":"normal","children":[{"_type":"span","_key":"key-8-pdqvr","text":"Voima-Jyri 500 -projekti viittaa 500 kilon yhteistulokseen voimanostossa (kyykky, penkki, maastanosto). Voima-Jyrin tavoitteena on 500 kilon haamurajan rikkominen. Projektiin on myös liitetty erilaisia dieettitavoitteita ja aerobisen kunnon kohottamista. Voima-Jyri 500-projekti toimii inspiraation lähteenä myös maltillisemmilla tavoitteilla treenaaville.\n\n"},{"_type":"span","_key":"key-9-ail5o","text":"Voima-Jyrillä on usean vuoden kokemus tavoitteellisesta voimaharjoittelusta ja kilpailutausta usemmasta lajista. Voima-Jyrin harjoittelee valmentajien valvonnassa. Hänen harjoitteitaan tai harjoitusperiaatteitaan ei siis kannata sellaisenaan kopioida."}]},{"_type":"block","_key":"key-12-9deik","style":"h2","children":[{"_type":"span","_key":"key-11-5cll2","text":"Tähän mennessä tapahtunut"}]},{"_type":"block","_key":"key-16-b8tyw","style":"normal","children":[{"_type":"span","_key":"key-13-uoa6e","text":"Voima-Jyri 500 -projekti alkoi kesällä 2011. Tällä sivulla seuraamme projektin etenemistä ja luomme katsauksen Voima-Jyrin aikaisempiin saavutuksiin.\n\n"},{"_type":"span","_key":"key-14-bvhhu","text":"Tästä kaikki alkoi","marks":["strong"]},{"_type":"span","_key":"key-15-qw12u","text":": Voima-Jyrin ja Iso-Esan valmennusyhteistyö käynnistyi kesällä 2011."}]},{"_type":"block","_key":"key-18-2ed9g","style":"h3","children":[{"_type":"span","_key":"key-17-bdtb5","text":"Tuotantokaudet"}]},{"_type":"block","_key":"key-22-iyr93","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-20-4nq1b","text":"yhteenveto tuotantokausista","marks":["key-19-5k8kx"]},{"_type":"span","_key":"key-21-hsssf","text":" 2010 alkaen"}],"markDefs":[{"_type":"link","_key":"key-19-5k8kx","href":"http://hyvoimailijat.com/?page_id=417"}]},{"_type":"image","_key":"key-25-nlza7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GM5V8M4B92290WFAKAE9M.png","url":"/_emdash/api/media/file/01KZ3GM5V8M4B92290WFAKAE9M.png"},"alt":"vj500logokausi5"},{"_type":"image","_key":"key-28-z1tu7","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GM9B94X21PWRAEHSACD3K.png","url":"/_emdash/api/media/file/01KZ3GM9B94X21PWRAEHSACD3K.png"},"alt":"elclasico"},{"_type":"image","_key":"key-31-mvr96","asset":{"_type":"reference","_ref":"/_emdash/api/media/file/01KZ3GMY92BX7MHKZPYDS2KCVZ.png","url":"/_emdash/api/media/file/01KZ3GMY92BX7MHKZPYDS2KCVZ.png"},"alt":"onlinelogomaker-082614-1428082614-1458082614-1519"},{"_type":"block","_key":"key-37-d3dud","style":"h3","children":[{"_type":"span","_key":"key-36-7ldyp","text":"Videot"}]},{"_type":"block","_key":"key-39-hi789","style":"h3","children":[{"_type":"span","_key":"key-38-i6zno","text":""}]},{"_type":"block","_key":"key-44-hlx40","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-41-b9f2i","text":"Voima-Jyrin 100 kunnian päivää","marks":["key-40-rnazb"]},{"_type":"span","_key":"key-42-d1k4o","text":" (julkaistu 26.8.2015) "},{"_type":"span","_key":"key-43-hpszs","text":"UUSI","marks":["strong"]}],"markDefs":[{"_type":"link","_key":"key-40-rnazb","href":"http://hyvoimailijat.com/?page_id=983"}]},{"_type":"block","_key":"key-48-mhmpv","style":"normal","listItem":"bullet","level":1,"children":[{"_type":"span","_key":"key-46-128uk","text":"Voima-Jyrin pääsiäisspecial 2015","marks":["key-45-iinib"]},{"_type"